// === ESTRAI CONTESTO CON GROUNDING ===
const results = $json.result || [];
const question = $('Estrai Domanda').item.json.question;

// Grounding assoluto: se 0 risultati, dichiara
if (!results || results.length === 0) {
  return [{
    json: {
      grounding_ok: false,
      context: '',
      sources: [],
      question: question,
      message: 'Nessun contesto pertinente trovato nella Knowledge Base.'
    }
  }];
}

// Estrai chunk + metadati
const chunks = results.map((r, i) => {
  const p = r.payload || {};
  return {
    rank: i + 1,
    score: r.score,
    text: p.text_content || '',
    source: p.source_reference || p.chunk_id || 'unknown',
    type: p.document_type || 'unknown',
    section: p.section_title || null
  };
});

// Componi contesto numerato per l'LLM
const contextText = chunks.map(c =>
  `[FONTE ${c.rank}] (score: ${c.score.toFixed(3)}, tipo: ${c.type})\n${c.text}\n`
).join('\n---\n');

return [{
  json: {
    grounding_ok: true,
    context: contextText,
    sources: chunks.map(c => ({ rank: c.rank, source: c.source, score: c.score })),
    question: question,
    chunk_count: chunks.length
  }
}];
